UPDATE `broadcast_text` SET `MaleText`='你的风度哪去了，兄弟？让我们欢迎这些客人吧。' WHERE `ID`=11706;
UPDATE `broadcast_text` SET `MaleText`='你们会很痛苦……' WHERE `ID`=11707;
UPDATE `broadcast_text` SET `MaleText`='哦，非常痛苦……' WHERE `ID`=11708;
