UPDATE `broadcast_text` SET `MaleText`='前进！前线在等待着我们！' WHERE `ID`=12113;
UPDATE `broadcast_text` SET `MaleText`='呼哧！这真是不容易，$r。很久没有见到天灾军团主动攻击了，自从……$B$B<卫兵迪迪尔喘了几口粗气。>$B$B自从上一次大战以后……' WHERE `ID`=12114;
UPDATE `broadcast_text` SET `MaleText`='留神……暗夜精灵回来了！' WHERE `ID`=12115;
