UPDATE `broadcast_text` SET `MaleText`='%s得意地盯着顾问瓦尔文。' WHERE `ID`=12584;
UPDATE `broadcast_text` SET `MaleText`='%s听完高级执行官的话，咧嘴而笑。' WHERE `ID`=12585;
UPDATE `broadcast_text` SET `MaleText`='喋喋不休的讨论令%s感到厌烦。' WHERE `ID`=12586;
