UPDATE `broadcast_text` SET `MaleText`='%s心不在焉地摆弄着他的护甲，显然对这场讨论提不起兴趣。' WHERE `ID`=12588;
UPDATE `broadcast_text` SET `MaleText`='%s看上去很不自在。' WHERE `ID`=12589;
UPDATE `broadcast_text` SET `MaleText`='%s不耐烦地跺着脚。' WHERE `ID`=12590;
UPDATE `broadcast_text` SET `MaleText`='%s怒目注视着卫兵。' WHERE `ID`=12591;
