UPDATE `broadcast_text` SET `MaleText`='快说，远行者！你带来了什么消息？' WHERE `ID`=12604;
UPDATE `broadcast_text` SET `FemaleText`='长官，远行者索兰娜告诉我，对塞布提拉和塞布努瓦的攻势正在进行中。她招募到了一个可靠的年轻人来帮助她处理各种状况。另外，楼上的药剂师提到一种药剂，他相信那也可以帮到我们解决巨魔。' WHERE `ID`=12605;
UPDATE `broadcast_text` SET `FemaleText`='%s慌乱地把目光从赫里奥斯中尉身上转开。' WHERE `ID`=12606;
