UPDATE `broadcast_text` SET `MaleText`='是不是啊？这么棒？' WHERE `ID`=13702;
UPDATE `broadcast_text` SET `MaleText`='显然不是……' WHERE `ID`=13703;
UPDATE `broadcast_text` SET `MaleText`='还是鸡肉……' WHERE `ID`=13704;
UPDATE `broadcast_text` SET `MaleText`='我恨你，曲奇。' WHERE `ID`=13705;
UPDATE `broadcast_text` SET `FemaleText`='<女祭司伊尔蒂娜怀疑地看着你。>' WHERE `ID`=13706;
UPDATE `broadcast_text` SET `FemaleText`='我是个暗夜精灵，陌生人。虽然你也许对我的种族一无所知，但我们早已对你和你的祖先了如指掌。你可以不把自己称为艾瑞达人。但是，在外形上你们有很多相似点。$B$B你帮了我的朋友们，我对此非常感谢；从现在开始，你就要独自走上危机四伏的道路。也许过不了多久，你可以消除我心中的恐惧和疑虑。' WHERE `ID`=13707;
UPDATE `broadcast_text` SET `FemaleText`='你好，$r。你高尚的行为已经得到了认可。愿艾露恩保佑你。' WHERE `ID`=13708;
UPDATE `broadcast_text` SET `MaleText`='小心一点，陌生人。' WHERE `ID`=13709;
UPDATE `broadcast_text` SET `MaleText`='迄今为止，你帮了我们不少忙，$n。营地附近还有其他人需要你的帮助呢。$B$B别担心那些地精，我会妥善安排好一切的。' WHERE `ID`=13710;
UPDATE `broadcast_text` SET `FemaleText`='阿达曼特，你能看下这块石板，顺便试着翻译一下上面的符文吗？' WHERE `ID`=13711;
UPDATE `broadcast_text` SET `MaleText`='当然！没问题，亲爱的！' WHERE `ID`=13712;
UPDATE `broadcast_text` SET `MaleText`='嗯，让我看看那块石板。' WHERE `ID`=13713;
UPDATE `broadcast_text` SET `MaleText`='%s慢慢地读着石板，用他们的母语读着那些文字。' WHERE `ID`=13714;
UPDATE `broadcast_text` SET `MaleText`='天哪……纳迦督军！' WHERE `ID`=13715;
UPDATE `broadcast_text` SET `MaleText`='嗯，你不会喜欢这个消息的，小姑娘。这块石板是纳迦的交流工具。他们的首领督军斯雷提兹命令他的纳迦们用武力来抢夺这块岛屿。' WHERE `ID`=13716;
UPDATE `broadcast_text` SET `MaleText`='看上去他得到了纳沙塔的增援！' WHERE `ID`=13717;
UPDATE `broadcast_text` SET `MaleText`='我们必须得干点什么了！' WHERE `ID`=13718;
UPDATE `broadcast_text` SET `FemaleText`='谢谢你，阿达曼特。我想我知道谁最适合这项工作。' WHERE `ID`=13719;
UPDATE `broadcast_text` SET `FemaleText`='很高兴能再次见到你，$n。也许当事情都解决了之后，我可以告诉你有关那些我们丢失的无价之宝的事情……' WHERE `ID`=13720;
UPDATE `broadcast_text` SET `MaleText`='联盟竟敢深入我的堡垒？把荣耀堡的战俘带出来，让刽子手们待命！他们会为这次入侵付出生命的代价！' WHERE `ID`=13721;
UPDATE `broadcast_text` SET `MaleText`='萨尔的那个冒牌部落胆敢深入我的堡垒？把萨尔玛的战俘带出来，让刽子手们待命！他们会为这次入侵付出生命的代价！' WHERE `ID`=13722;
UPDATE `broadcast_text` SET `MaleText`='刽子手们已经就位了！把俘虏们准备好！' WHERE `ID`=13723;
UPDATE `broadcast_text` SET `MaleText`='马上处决一个战俘！先杀了那个矮人……他的废话太多了。' WHERE `ID`=13724;
