UPDATE `broadcast_text` SET `FemaleText`='%s拥抱着她的父亲。' WHERE `ID`=13747;
UPDATE `broadcast_text` SET `FemaleText`='你应该感谢$n安全地把我带回来，爸爸。' WHERE `ID`=13748;
