UPDATE `broadcast_text` SET `MaleText`='我的朋友们会……会……啊……', `FemaleText`='我的朋友们会……会……啊……' WHERE `ID`=14559;
UPDATE `broadcast_text` SET `MaleText`='逐日者必胜！', `FemaleText`='逐日者必胜！' WHERE `ID`=14560;
UPDATE `broadcast_text` SET `MaleText`='你这样做，无非是让不可避免的末日来得晚些……', `FemaleText`='你这样做，无非是让不可避免的末日来得晚些……' WHERE `ID`=14561;
UPDATE `broadcast_text` SET `MaleText`='我弄丢了风蚀的藏宝图。你还有多余的吗？', `FemaleText`='我弄丢了风蚀的藏宝图。你还有多余的吗？' WHERE `ID`=14562;
UPDATE `broadcast_text` SET `MaleText`='我是伊索姆，阿古斯之手三人执政团的老三。' WHERE `ID`=14563;
UPDATE `broadcast_text` SET `MaleText`='实际上，我有。我正准备把它裱起来，以博得铁炉堡的那些家伙们一笑，但是你想要的话，就给你吧。' WHERE `ID`=14564;
UPDATE `broadcast_text` SET `MaleText`='微风告诉我，我们的敌人正在行动，埃西恩。纳迦会再次进攻我们的。' WHERE `ID`=14565;
UPDATE `broadcast_text` SET `MaleText`='谨慎不代表我们要让敌人占据优势。' WHERE `ID`=14566;
UPDATE `broadcast_text` SET `MaleText`='很好。当最终的决定作出时，我会准备好的。希望那不会太晚。' WHERE `ID`=14567;
UPDATE `broadcast_text` SET `MaleText`='我们应该把事情做好，而不是不计后果。仍然有很多关于这个世界和这些敌人的东西需要我们去学习。' WHERE `ID`=14568;
UPDATE `broadcast_text` SET `MaleText`='当我们知道自己需要什么的时候，我们才会开始行动，老朋友。德鲁伊们已经证明了他们的智慧和独自决策的能力。' WHERE `ID`=14569;
UPDATE `broadcast_text` SET `MaleText`='这里躺着除草者格林萨姆的遗体，他是观察者杰哈恩的德鲁伊同伴。显然，当他想要逃出奴隶围栏时，他被迅速杀害了。' WHERE `ID`=14570;
UPDATE `broadcast_text` SET `MaleText`='我几乎要成功了！$B$B我来到这里是为了证明传说中的真菌巨人夸格米拉的存在。我完成了自己的愿望……理论上。$B$B你必须让我重获自由！作为回报，我会帮助你解决夸格米拉。' WHERE `ID`=14571;
UPDATE `broadcast_text` SET `MaleText`='保护太阳之门的能量护罩已经被解除了。太阳之门正处于不堪一击的状态！' WHERE `ID`=14572;
UPDATE `broadcast_text` SET `MaleText`='太阳之门必须稳定下来。集中你们的能量！', `FemaleText`='太阳之门必须稳定下来。集中你们的能量！' WHERE `ID`=14573;
UPDATE `broadcast_text` SET `MaleText`='好吧，拜特。我会让你出来。', `FemaleText`='好吧，拜特。我会让你出来。' WHERE `ID`=14574;
UPDATE `broadcast_text` SET `MaleText`='啊呀！看来你所制造的噪音已经引起了一些不必要的注意！' WHERE `ID`=14575;
UPDATE `broadcast_text` SET `MaleText`='很好。为了名誉和荣耀，冲啊！' WHERE `ID`=14576;
UPDATE `broadcast_text` SET `MaleText`='是谁胆敢在圣洁的阿隆索斯礼拜堂造次？' WHERE `ID`=14577;
UPDATE `broadcast_text` SET `MaleText`='哦，强大的夸格米拉，我们恳请你欢迎我们的到来！' WHERE `ID`=14578;
UPDATE `broadcast_text` SET `MaleText`='可恶！为你亵渎圣光的罪行忏悔吧！' WHERE `ID`=14580;
UPDATE `broadcast_text` SET `MaleText`='冒牌的圣骑士，露出你的真面目吧！准备面对圣光的愤怒吧！' WHERE `ID`=14581;
UPDATE `broadcast_text` SET `MaleText`='肮脏的动物！你们要囚禁我吗？' WHERE `ID`=14582;
