UPDATE `broadcast_text` SET `MaleText`='你知道，我们随时可以用地精替换你。你难道希望这样？' WHERE `ID`=17203;
UPDATE `broadcast_text` SET `MaleText`='我不敢相信你这个蠢货竟然为了这个去学校！谁知道他们在干什么吗？' WHERE `ID`=17204;
