UPDATE `broadcast_text` SET `FemaleText`='啊……' WHERE `ID`=20600;
UPDATE `broadcast_text` SET `MaleText`='鲁罗萨，我把艾维娜圣物委托给$n转交莫希斯·轻翼了。现在我必须彻底地回到翡翠梦境去了。不要让$n失败！' WHERE `ID`=20601;
UPDATE `broadcast_text` SET `FemaleText`='唔……这东西闻起来很有趣。' WHERE `ID`=20602;
UPDATE `broadcast_text` SET `FemaleText`='你的眼睛真大啊！' WHERE `ID`=20603;
UPDATE `broadcast_text` SET `FemaleText`='我不记得曾经有这么小过。' WHERE `ID`=20604;
