UPDATE `broadcast_text` SET `FemaleText`='我们必须在矿洞附近重建我们的要塞！' WHERE `ID`=21452;
UPDATE `broadcast_text` SET `MaleText`='<暗血监工咕哝着。>' WHERE `ID`=21453;
UPDATE `broadcast_text` SET `MaleText`='他们派你来杀我的吧，嗯？我早就猜到了……被恐怖支配的生物都一样。$B$B不过你……你和他们不一样……' WHERE `ID`=21454;
UPDATE `broadcast_text` SET `MaleText`='我是为你而来的，监工。', `FemaleText`='我是为你而来的，监工。' WHERE `ID`=21455;
