UPDATE `broadcast_text` SET `FemaleText`='欢迎你，冒险家。你来的正是时候。' WHERE `ID`=27044;
UPDATE `broadcast_text` SET `MaleText`='塞尔赞必须死，只有这样才能使怨灵停止那永无止境的哭泣！' WHERE `ID`=27045;
