UPDATE `broadcast_text` SET `FemaleText`='诺哈因，你说莫度鲁为什么还穿着这件可笑的袍子啊。他看上去就像那些刚刚逃出埃门谷的乡巴佬似的。' WHERE `ID`=27086;
UPDATE `broadcast_text` SET `MaleText`='火枪手，营救那些士兵！速度！', `FemaleText`='火枪手，营救那些士兵！速度！' WHERE `ID`=27087;
UPDATE `broadcast_text` SET `MaleText`='这是营救他的好时机！快去！', `FemaleText`='这是营救他的好时机！快去！' WHERE `ID`=27088;
UPDATE `broadcast_text` SET `MaleText`='火枪手，停止射击！那名士兵就在射程的安全范围之内！快去救他！', `FemaleText`='火枪手，停止射击！那名士兵就在射程的安全范围之内！快去救他！' WHERE `ID`=27089;
UPDATE `broadcast_text` SET `MaleText`='旧斯坦索姆……为什么送我回到这一时间流？', `FemaleText`='旧斯坦索姆……为什么送我回到这一时间流？' WHERE `ID`=27090;
UPDATE `broadcast_text` SET `FemaleText`='永恒之龙企图改变阿尔萨斯·米奈希尔王子的命运。$B$B你所熟悉的巫妖王在这一时间流里仍然是洛丹伦的王子，而且全心全意地为国效力。$B$B今天，阿尔萨斯做出了一个重大的决定，它所导致的后果，被我们时光守护者们称之为时间流的拐点。' WHERE `ID`=27091;
UPDATE `broadcast_text` SET `MaleText`='是什么决定？', `FemaleText`='是什么决定？' WHERE `ID`=27092;
UPDATE `broadcast_text` SET `FemaleText`='阿尔萨斯下令清洗斯坦索姆，杀死城内所有的居民。$B$B他发现了天灾军团在斯坦索姆传播瘟疫的证据。这种疾病不仅能致人死命。$B$B它还能让死于瘟疫的人复生成为无脑的僵尸，将他们统统改造成天灾军团的战争机器。' WHERE `ID`=27093;
UPDATE `broadcast_text` SET `MaleText`='永恒之龙打算如何破坏这一时间流呢？', `FemaleText`='永恒之龙打算如何破坏这一时间流呢？' WHERE `ID`=27094;
UPDATE `broadcast_text` SET `MaleText`='谢谢你掩护我！下面简直就像精神病院！', `FemaleText`='谢谢你掩护我！下面简直就像精神病院！' WHERE `ID`=27095;
