UPDATE `broadcast_text` SET `MaleText`='你好，$n。很高兴再见到你。' WHERE `ID`=39110;
UPDATE `broadcast_text` SET `MaleText`='为杰罗德工作并不是那么糟糕。他也许偶尔会发发脾气，但他付的薪水很高。当我不能按进度完成工作的时候，他甚至还会帮我的忙。' WHERE `ID`=39111;
UPDATE `broadcast_text` SET `MaleText`='我能为你做些什么？' WHERE `ID`=39112;
