UPDATE `broadcast_text` SET `FemaleText`='我能怎样帮你，$c？' WHERE `ID`=45564;
UPDATE `broadcast_text` SET `MaleText`='我知道你有自己的办法。我不在乎他们对于你和阿利卡拉的关系有着怎样的议论。那些话到我这里就结束了！' WHERE `ID`=45565;
