UPDATE `broadcast_text` SET `FemaleText`='吉德文，下次你可以和我一起坐在前面。' WHERE `ID`=45594;
UPDATE `broadcast_text` SET `MaleText`='也许我不想了。也许我更愿意和我的新朋友们坐在后面。前面有一股马味儿。' WHERE `ID`=45595;
