UPDATE `broadcast_text` SET `MaleText`='佩波欢快地四下跳跃着，消失在远方。' WHERE `ID`=49814;
UPDATE `broadcast_text` SET `MaleText`='佩波欢快地在你腿边跳上跳下，然后飞也似地消失在远方。' WHERE `ID`=49815;
