UPDATE `broadcast_text` SET `FemaleText`='戴姆维克就在东南方的洞穴入口处。' WHERE `ID`=49832;
UPDATE `broadcast_text` SET `MaleText`='卡亚矿石没了，这些猴子也因为矿石而变聪明了！保护好那个矿工，$n。' WHERE `ID`=49833;
UPDATE `broadcast_text` SET `MaleText`='以锈水财阀的名义，这里的矿是我的！' WHERE `ID`=49834;
UPDATE `broadcast_text` SET `FemaleText`='我们要想保住性命，就需要结交一些新朋友。希望那些兽人不会一见面就把你干掉。' WHERE `ID`=49835;
UPDATE `broadcast_text` SET `MaleText`='和你合作感觉很愉快，$g小伙子:小姑娘;。$b$b希望今后能与你再次携手。' WHERE `ID`=49836;
