UPDATE `broadcast_text` SET `MaleText`='死吧！！！', `FemaleText`='死吧！！！' WHERE `ID`=49839;
UPDATE `broadcast_text` SET `MaleText`='我们要把这地方焚毁殆尽！', `FemaleText`='我们要把这地方焚毁殆尽！' WHERE `ID`=49840;
UPDATE `broadcast_text` SET `MaleText`='受够你这些豌豆射手了。让它们往这儿打！', `FemaleText`='受够你这些豌豆射手了。让它们往这儿打！' WHERE `ID`=49841;
UPDATE `broadcast_text` SET `FemaleText`='深岩之洲近年来改变了许多。都快认不出来了。$B$B但是……我并没有被腐化。并没有受到远古之神的影响。看来有时只有在自由被剥夺的情况下，人们才能真正意识到它的珍贵。' WHERE `ID`=49842;
UPDATE `broadcast_text` SET `FemaleText`='基拉格·血牙应该就在通向西边的路上，地精。' WHERE `ID`=49843;
UPDATE `broadcast_text` SET `MaleText`='%s开始施放烈焰升腾！' WHERE `ID`=49844;
UPDATE `broadcast_text` SET `FemaleText`='我认识你。我要感谢你。如果不是你，我可能还会深陷在已经将我吞噬无数个岁月的腐蚀力量中。$B$B欢迎来到我的家，深岩之洲。与曾经的深岩之洲相比，这里大概只能算是一个影子。但我现在是自由的。承受过那么多磨难之后，我已经深深地明白，自由是多么可贵。$B$B不知道你为什么会到这里来，但我希望你能在这高大的石墙中找到你所需要的一切。祝你平安，$n。' WHERE `ID`=49845;
UPDATE `broadcast_text` SET `MaleText`='用你的杂草清理者割倒这些植物，小地精！' WHERE `ID`=49846;
UPDATE `broadcast_text` SET `MaleText`='这台挖掘机有些生锈了，可看起来还能使用。' WHERE `ID`=49847;
UPDATE `broadcast_text` SET `MaleText`='按下带有“经过黑铁酒吧”标签的按钮。', `FemaleText`='按下带有“经过黑铁酒吧”标签的按钮。' WHERE `ID`=49848;
UPDATE `broadcast_text` SET `MaleText`='按下带有“进入住宅区”标签的按钮。', `FemaleText`='按下带有“进入住宅区”标签的按钮。' WHERE `ID`=49849;
