UPDATE `broadcast_text` SET `MaleText`='我已经在你的武器上涂了特殊的浆液。把它注入敌人体内。如果注入过多，就会超出他们身体的负荷。' WHERE `ID`=63584;
UPDATE `broadcast_text` SET `MaleText`='来吧，唤醒者。我们去会会敌人。' WHERE `ID`=63585;
