UPDATE `broadcast_text` SET `MaleText`='你已是我的盘中餐了！' WHERE `ID`=64784;
UPDATE `broadcast_text` SET `MaleText`='和乌克一起去烹饪！' WHERE `ID`=64785;
UPDATE `broadcast_text` SET `MaleText`='蠢蛋炖肉，就要端上来了！' WHERE `ID`=64786;
UPDATE `broadcast_text` SET `MaleText`='狂欢时间到！' WHERE `ID`=64787;
UPDATE `broadcast_text` SET `MaleText`='那蠢货要倒霉了！' WHERE `ID`=64788;
UPDATE `broadcast_text` SET `MaleText`='跳吧，蠢货！跳吧！' WHERE `ID`=64789;
