UPDATE `broadcast_text` SET `MaleText`='啪啪啪啪，嘭！' WHERE `ID`=64791;
UPDATE `broadcast_text` SET `MaleText`='那小子要被痛扁一顿了！' WHERE `ID`=64792;
UPDATE `broadcast_text` SET `MaleText`='给你一个礼物。' WHERE `ID`=64793;
