UPDATE `broadcast_text` SET `MaleText`='|TInterface\\Icons\\inv_misc_monsterfang_02.blp:20|t %s用他的|cFFFF0000|Hspell:126187|h[钳颚]|h|r诱捕猎物！杀了他！' WHERE `ID`=65075;
UPDATE `broadcast_text` SET `MaleText`='人必须尊重他的家族。' WHERE `ID`=65076;
UPDATE `broadcast_text` SET `MaleText`='当缚魂魔袋看到指导者的灵魂被摧毁的时候，它开心地笑了起来。' WHERE `ID`=65077;
UPDATE `broadcast_text` SET `MaleText`='尽管缚魂魔袋看上去不大愿意进入大厅，但是还是跟了上来。' WHERE `ID`=65078;
UPDATE `broadcast_text` SET `MaleText`='一支人数众多的军队拿什么做点心？$B$B……$B$B撤退！' WHERE `ID`=65079;
UPDATE `broadcast_text` SET `MaleText`='我不是以治疗者而是牧师的身份来见你！' WHERE `ID`=65080;
UPDATE `broadcast_text` SET `MaleText`='不要问我怎么对付术士。我避开他们。哈哈哈哈！' WHERE `ID`=65081;
UPDATE `broadcast_text` SET `MaleText`='坦克为什么会在战斗之前感到紧张？$B$B……$B$B因为他们总是很忐忑！' WHERE `ID`=65082;
UPDATE `broadcast_text` SET `MaleText`='如果瓦里安国王倒台，会怎么样？$B$B……$B$B我不知道，但应该会发生不小的震动！' WHERE `ID`=65083;
UPDATE `broadcast_text` SET `MaleText`='……呃……！$B$B……什么是……什么是“内脏”……？' WHERE `ID`=65084;
UPDATE `broadcast_text` SET `MaleText`='我实在不忍心看。' WHERE `ID`=65085;
UPDATE `broadcast_text` SET `MaleText`='缚魂魔袋一言不发地进入第二个大厅。' WHERE `ID`=65086;
UPDATE `broadcast_text` SET `MaleText`='啊，这不是我最仰慕的刺客大师吗！我一直希望能在潘达利亚找到你呢。' WHERE `ID`=65087;
UPDATE `broadcast_text` SET `MaleText`='很好。我们谈谈吧。' WHERE `ID`=65088;
UPDATE `broadcast_text` SET `MaleText`='童福！拿酒来。' WHERE `ID`=65089;
UPDATE `broadcast_text` SET `MaleText`='我的父亲死亡之翼，曾经想摧毁整个艾泽拉斯。' WHERE `ID`=65090;
UPDATE `broadcast_text` SET `MaleText`='没错，他是误入歧途，可他却说对了一件事——我们的世界……确实脆弱不堪。' WHERE `ID`=65091;
UPDATE `broadcast_text` SET `MaleText`='我们是晦暗宇宙中的一点光亮。是飘摇在暴风雨中的烛光。' WHERE `ID`=65092;
UPDATE `broadcast_text` SET `MaleText`='有时我会想，正是我们这个世界的动荡，逼疯了我的父亲。' WHERE `ID`=65093;
UPDATE `broadcast_text` SET `MaleText`='啊，谢谢你，童福。' WHERE `ID`=65094;
UPDATE `broadcast_text` SET `MaleText`='现在，言归正传——我觉得一场末世浩劫正在酝酿。不，我说的不是联盟和部落之间的冲突。' WHERE `ID`=65095;
UPDATE `broadcast_text` SET `MaleText`='相信我——加尔鲁什·地狱咆哮在塞拉摩的所作所为，跟现在降临于我们脆弱家园的浩劫相比，根本算不了什么。' WHERE `ID`=65096;
UPDATE `broadcast_text` SET `MaleText`='可战争深深困扰着我。你理解我的顾虑吗？' WHERE `ID`=65097;
UPDATE `broadcast_text` SET `MaleText`='四分五裂的艾泽拉斯根本无力对抗黑暗。' WHERE `ID`=65098;
UPDATE `broadcast_text` SET `MaleText`='这场战争必须尽快结束。否则，它会耗尽我们的力量！' WHERE `ID`=65099;
UPDATE `broadcast_text` SET `MaleText`='请你相信，联盟在这场战役中，能得到我毫无保留、坚定不移的支持。' WHERE `ID`=65100;
UPDATE `broadcast_text` SET `MaleText`='你大可放心，我的忠诚与部落同在。' WHERE `ID`=65101;
UPDATE `broadcast_text` SET `MaleText`='我们该如何迅速果断地平息这场冲突？相信答案就在你们这些英雄心里。' WHERE `ID`=65102;
UPDATE `broadcast_text` SET `MaleText`='我们必须确定你能够执行这项任务……并把你武装起来。' WHERE `ID`=65103;
UPDATE `broadcast_text` SET `MaleText`='尽量保命！我们才刚刚开始这场传奇之旅。' WHERE `ID`=65104;
UPDATE `broadcast_text` SET `MaleText`='啊！我的英雄回来了。' WHERE `ID`=65105;
UPDATE `broadcast_text` SET `MaleText`='平台就在山上。多加小心，访客几乎全都有去无回。' WHERE `ID`=65106;
UPDATE `broadcast_text` SET `MaleText`='你看起来面色苍白，朋友！相信你还没有被恐惧打败吧？' WHERE `ID`=65107;
UPDATE `broadcast_text` SET `MaleText`='请允许我收拾一下东西，然后我会前去找你。' WHERE `ID`=65108;
UPDATE `broadcast_text` SET `MaleText`='我经常来这儿思考。这景色真让人叹为观止，你觉得呢？' WHERE `ID`=65109;
UPDATE `broadcast_text` SET `MaleText`='潘达利亚真是一颗明珠。美轮美奂。使你想要去保护她，是吧？' WHERE `ID`=65110;
UPDATE `broadcast_text` SET `MaleText`='我对艾泽拉斯也有同感。' WHERE `ID`=65111;
UPDATE `broadcast_text` SET `MaleText`='你成就斐然，我的朋友。我保证，这只是我们合作的开始。' WHERE `ID`=65112;
UPDATE `broadcast_text` SET `MaleText`='向你的手下败将学习力量。' WHERE `ID`=65113;
UPDATE `broadcast_text` SET `MaleText`='向不如你聪明的人学习智慧。' WHERE `ID`=65114;
UPDATE `broadcast_text` SET `MaleText`='看！它就是你所战胜的恐惧实体。愿它将恐惧注入你敌人的体内！' WHERE `ID`=65115;
UPDATE `broadcast_text` SET `MaleText`='终于等到了我要给你的礼物。别搞错了——黑龙军团还活着！' WHERE `ID`=65116;
UPDATE `broadcast_text` SET `MaleText`='好了。我的工作完成了。你现在能大大提高任何感染煞能的武器的威力。' WHERE `ID`=65117;
UPDATE `broadcast_text` SET `MaleText`='我们才刚刚开始，朋友！最大的挑战还在前头。' WHERE `ID`=65118;
UPDATE `broadcast_text` SET `MaleText`='但当战火烧到这片海岸时，你和我都会做好准备！' WHERE `ID`=65119;
UPDATE `broadcast_text` SET `MaleText`='很高兴再次见到你，$n！我相信我在拉文霍德给你的武器，已经派上大用场了，对吗？$b$b在潘达利亚，我有另一个“任务”给你。这将再次需要你的所有技能，我再次向你保证……这将是值得的！$b$b在我们开始前，重要的是你自己要熟悉地形。一旦你获得更多的经验，就来拜访我。' WHERE `ID`=65120;
UPDATE `broadcast_text` SET `MaleText`='你好，又见面了。$n，是它吗？是的，没错……我相信我们在东部王国留下了一些未完成的事业。你怎么找到潘达利亚的？$b$b如果你赢得这次挑战，我便再给你另一个任务。我保证这值得你去做。$b$b在我们开始前，重要的是你自己要熟悉地形。一旦你获得更多的经验，就来拜访我。' WHERE `ID`=65121;
UPDATE `broadcast_text` SET `MaleText`='<黑王子上下打量了你一番。>$b$b很高兴见到你，$c，探索新世界的先锋。在神秘大陆潘达利亚上冒险的感觉如何？$b$b你看起来就像是个办事可靠的人。我希望当你完成对这块大陆的游历之后，就立即回来找我。$b$b我会在这里等你。' WHERE `ID`=65122;
UPDATE `broadcast_text` SET `MaleText`='我所选择的名字是“拉希奥”。据我所知，我是最后一条黑龙。$b$b我的父亲是死亡之翼。他是灭世者、死亡的化身、毁灭者……但我希望你不会因此而排斥我。$b$b我不爱我的父亲，他的堕落摧毁了我的族群，我也不喜欢红龙军团，他把我的蛋偷去做试验，期望改造我。$b$b这么说吧，我如今是……孑然一身。而且，我一直在寻找志同道合的英雄。' WHERE `ID`=65123;
UPDATE `broadcast_text` SET `MaleText`='你是谁？', `FemaleText`='你是谁？' WHERE `ID`=65124;
UPDATE `broadcast_text` SET `MaleText`='你在潘达利亚做什么？', `FemaleText`='你在潘达利亚做什么？' WHERE `ID`=65125;
UPDATE `broadcast_text` SET `MaleText`='我当然可以有一些秘密。你不同意吗，$n？$b$b迷雾散去后不久，我就到达了……在我的同事拉文霍德了解了一次远离海岸的海战后，我可以飞到这里。$b$b这里已经被隐藏了一万年。我才刚刚开始探索之旅！' WHERE `ID`=65126;
UPDATE `broadcast_text` SET `MaleText`='你回来我很高兴，$n！我相信你现在已经适应了潘达利亚这片奇怪的新大陆，对吗？$b$b你过去已经证明了自己，这样我们就可以免去任何类似的测试或试验。让我们马上开始。$b$b你准备好改变世界了吗？' WHERE `ID`=65127;
UPDATE `broadcast_text` SET `MaleText`='欢迎，$c！我的眼线遍布潘达利亚，我得知，你一直都在忙碌着。我敬佩具备……“主动性”的凡人们。$b$b我们正处在一个历史的转折点上。如果你愿意带着我去迎接命运，我会确保你的付出能得到丰厚的回报。' WHERE `ID`=65128;
UPDATE `broadcast_text` SET `MaleText`='我们的熊猫人战役才刚刚开始，$n。' WHERE `ID`=65129;
UPDATE `broadcast_text` SET `FemaleText`='我相信我们最终可以找到我父亲的青春之池。我们可以为泰兰德提供尽可能多的信息。' WHERE `ID`=65130;
UPDATE `broadcast_text` SET `FemaleText`='因为我们来到这片新的土地，所以我的哨兵面临许多危险。我们准备好迎接任何挑战。' WHERE `ID`=65131;
UPDATE `broadcast_text` SET `FemaleText`='在进入四风谷后，我军的士气有所提高。' WHERE `ID`=65132;
UPDATE `broadcast_text` SET `FemaleText`='四风谷真是个的天堂。' WHERE `ID`=65133;
UPDATE `broadcast_text` SET `FemaleText`='亲眼见到这个地方是我父亲的梦想。我必须在这里完成他的心愿。' WHERE `ID`=65134;
UPDATE `broadcast_text` SET `MaleText`='从南部海岸刮来了一阵恶风。你准备好了吗？' WHERE `ID`=65135;
UPDATE `broadcast_text` SET `FemaleText`='在收集我们所要的信息之前，我们都在这个谷里休息。然后，我们必须想方设法回家。' WHERE `ID`=65136;
UPDATE `broadcast_text` SET `MaleText`='这里有一些屏障保护着四风谷，阴止我使用传送门魔法。' WHERE `ID`=65137;
UPDATE `broadcast_text` SET `FemaleText`='我们能在这个四风谷遇见还真巧。' WHERE `ID`=65138;
UPDATE `broadcast_text` SET `FemaleText`='加尔鲁什的狂妄摧毁了锦绣谷。这是无法治愈的创伤。' WHERE `ID`=65139;
UPDATE `broadcast_text` SET `FemaleText`='泰兰德派我们来这里寻找圣光。' WHERE `ID`=65140;
UPDATE `broadcast_text` SET `FemaleText`='这里的树比我在南部丛林见过的都更漂亮。' WHERE `ID`=65141;
UPDATE `broadcast_text` SET `FemaleText`='我从来没有见过像这样的地方。' WHERE `ID`=65142;
UPDATE `broadcast_text` SET `FemaleText`='这山谷里的池水莫非就是传说中的“青春之池”？也许我们可以再次掌握永生……' WHERE `ID`=65143;
UPDATE `broadcast_text` SET `FemaleText`='我们已经听说了魔古族遍布四风谷的消息。他们不会胜过我们的。' WHERE `ID`=65144;
UPDATE `broadcast_text` SET `FemaleText`='我们在研究池水的同时，还会巡逻城市的边界，保护这里的人。' WHERE `ID`=65145;
UPDATE `broadcast_text` SET `FemaleText`='说实话，我起初并不相信瓦尔德林看见的幻像。但这地方确实散发着不同寻常的魔法之力——难道这就是传说中的“青春之池”？' WHERE `ID`=65146;
UPDATE `broadcast_text` SET `MaleText`='如果你有时间，你应该参观滨岸有名的酿月祭。我会酿造一些著名的昆莱劲酒。' WHERE `ID`=65147;
UPDATE `broadcast_text` SET `MaleText`='传说在这四风谷发生了大会战，许多勇敢武僧的鲜血将金色的原野染成了红色。魔古皇帝雷电之王雷神的军队战斗野蛮，但是最终被攻克。' WHERE `ID`=65148;
UPDATE `broadcast_text` SET `MaleText`='去死吧，加丁！杀了他！' WHERE `ID`=65149;
UPDATE `broadcast_text` SET `MaleText`='我有两百多艘船，唯独载着我儿子的那艘……不见了！' WHERE `ID`=65150;
UPDATE `broadcast_text` SET `MaleText`='我很抱歉，可我暂时还不能回去。' WHERE `ID`=65151;
UPDATE `broadcast_text` SET `MaleText`='我决心去寻找那座溪谷……溪谷……溪谷……' WHERE `ID`=65152;
UPDATE `broadcast_text` SET `MaleText`='抢占那片海滩，将那岛屿染成红色！' WHERE `ID`=65153;
UPDATE `broadcast_text` SET `MaleText`='|TInterface\\Icons\\ability_warlock_improvedsoulleech:20|t你受|cFFFF0000|Hspell:126228|h[撕裂的灵魂]|h|r的影响！杀了它！' WHERE `ID`=65154;
UPDATE `broadcast_text` SET `MaleText`='雷神溃败后的这些天，四风谷被最深黑色的乌云笼罩。雷神在他临终前召唤出异世的风暴笼罩四风谷，伴随着降雨和锯齿状的闪电长矛劈落在山上。' WHERE `ID`=65155;
UPDATE `broadcast_text` SET `MaleText`='亡者的鲜血被风暴冲刷到琼花湖，把湖水染成深红色。凭借最后一口气，风暴袭击了湖中心，点燃了湖水本身。湖水被烧了很多天，呈现出深红色。' WHERE `ID`=65156;
UPDATE `broadcast_text` SET `MaleText`='当大火平息，云端翔龙孵化，在湖中心周围飞行。它的鳞屑点燃风暴和火焰。在它所到之处，天空中呈现祥云朵朵。我的人把它称为阿拉尼，风暴之子的意思。' WHERE `ID`=65157;
UPDATE `broadcast_text` SET `MaleText`='他们说，阿拉尼只能看到最亮的闪电，也许只能听到最响惊雷的回声。你如果希望得到她的注意，则需要利用催生了她的天空本身。' WHERE `ID`=65158;
UPDATE `broadcast_text` SET `MaleText`='然后发生了什么事？', `FemaleText`='然后发生了什么事？' WHERE `ID`=65159;
UPDATE `broadcast_text` SET `MaleText`='你好，朋友！我这里通常不会有太多人造访，你是否想听听锦绣谷的故事？' WHERE `ID`=65160;
UPDATE `broadcast_text` SET `MaleText`='我想！', `FemaleText`='我想！' WHERE `ID`=65161;
UPDATE `broadcast_text` SET `MaleText`='这很有意义！', `FemaleText`='这很有意义！' WHERE `ID`=65162;
UPDATE `broadcast_text` SET `MaleText`='该死的蠢蛋！啤酒是给猢狲的！' WHERE `ID`=65164;
UPDATE `broadcast_text` SET `MaleText`='倒酒！' WHERE `ID`=65165;
UPDATE `broadcast_text` SET `MaleText`='没有你的啤酒！' WHERE `ID`=65166;
UPDATE `broadcast_text` SET `MaleText`='嘿呀！' WHERE `ID`=65167;
UPDATE `broadcast_text` SET `MaleText`='魔古族的古老地宫，数千年来封存未动，谁知道里面有什么秘密？' WHERE `ID`=65168;
UPDATE `broadcast_text` SET `MaleText`='人人为我！我为乌克！' WHERE `ID`=65169;
UPDATE `broadcast_text` SET `MaleText`='许多年轻的熊猫人都在这墓穴里……蒸发了。时刻保持警惕。' WHERE `ID`=65170;
UPDATE `broadcast_text` SET `MaleText`='魔古族对大地的石头有着极大的控制力。他们的魔法直到数个世纪之后余力犹存。' WHERE `ID`=65171;
UPDATE `broadcast_text` SET `MaleText`='庞大的魁麟似乎在把守大门。小心前行，以免唤醒它们。' WHERE `ID`=65172;
UPDATE `broadcast_text` SET `MaleText`='真险哪！' WHERE `ID`=65173;
UPDATE `broadcast_text` SET `MaleText`='随着守卫的死去，大门的装置似乎被激活了。不知我们会在里面有何遭遇。' WHERE `ID`=65174;
UPDATE `broadcast_text` SET `MaleText`='我们似乎唤醒了什么东西的灵魂。' WHERE `ID`=65175;
UPDATE `broadcast_text` SET `MaleText`='看来传说是真的……' WHERE `ID`=65176;
UPDATE `broadcast_text` SET `MaleText`='我们打扰了不该打扰的东西。决不能让他逃离这囚牢！你必须消灭他！' WHERE `ID`=65177;
UPDATE `broadcast_text` SET `MaleText`='受诅者魔封遭到了四位魔古皇帝的背叛，他的身体每次都被摧毁，然后再度复活。' WHERE `ID`=65178;
UPDATE `broadcast_text` SET `MaleText`='猢狲打刀手！集合！' WHERE `ID`=65179;
UPDATE `broadcast_text` SET `MaleText`='这不会是我们最后一次看见魔封……' WHERE `ID`=65180;
UPDATE `broadcast_text` SET `MaleText`='赞达拉——魔古族的古老盟友！他们一定在宝库深处寻找传说中的武器！' WHERE `ID`=65181;
UPDATE `broadcast_text` SET `MaleText`='蠢蛋！' WHERE `ID`=65182;
UPDATE `broadcast_text` SET `MaleText`='不速之客！' WHERE `ID`=65183;
UPDATE `broadcast_text` SET `MaleText`='嘿呀！' WHERE `ID`=65184;
UPDATE `broadcast_text` SET `MaleText`='你没有拿酒！' WHERE `ID`=65185;
UPDATE `broadcast_text` SET `MaleText`='拿下他们的头目！' WHERE `ID`=65186;
UPDATE `broadcast_text` SET `MaleText`='为了乌克头领！' WHERE `ID`=65187;
UPDATE `broadcast_text` SET `MaleText`='抱歉我没有早点告诉你！在这宝库里有一把威力无穷的武器！阻止他们！' WHERE `ID`=65188;
UPDATE `broadcast_text` SET `MaleText`='我要留下，进一步调查这里……' WHERE `ID`=65189;
UPDATE `broadcast_text` SET `MaleText`='这台子底下有个秘密通道，来这边！' WHERE `ID`=65190;
UPDATE `broadcast_text` SET `MaleText`='看看地上的灰尘，这黑暗的殿堂已有几百年无人踏入了。' WHERE `ID`=65191;
UPDATE `broadcast_text` SET `MaleText`='魔古族曾奴役潘达利亚的所有种族，并让他们屈从于自己的邪恶意志。' WHERE `ID`=65192;
UPDATE `broadcast_text` SET `MaleText`='这些锦鱼人被囚禁在永恒的奴役之中。' WHERE `ID`=65193;
UPDATE `broadcast_text` SET `MaleText`='我听见了微弱的嗡鸣声。是从这个方向传来的！' WHERE `ID`=65194;
UPDATE `broadcast_text` SET `MaleText`='那就结束了。可是……地下藏有多少这种机器？我们对魔古族的黑暗秘密又知道多少？' WHERE `ID`=65195;
UPDATE `broadcast_text` SET `MaleText`='恐怕我们对抗远古敌人的战斗还远未结束。' WHERE `ID`=65196;
UPDATE `broadcast_text` SET `MaleText`='难以置信！一台真真切切的魔古建造机器。' WHERE `ID`=65197;
UPDATE `broadcast_text` SET `MaleText`='千万不能让它落入恶人之手。' WHERE `ID`=65198;
UPDATE `broadcast_text` SET `MaleText`='无数没有灵魂的、畸形的怪物，浩浩荡荡……想到这机器中会涌出怎样的邪恶，我就打寒颤。' WHERE `ID`=65199;
UPDATE `broadcast_text` SET `MaleText`='就在此地，就趁现在，必须在它危害潘达利亚之前摧毁它。' WHERE `ID`=65200;
UPDATE `broadcast_text` SET `MaleText`='打开这台机器，我会帮你锁住后面的门。' WHERE `ID`=65201;
UPDATE `broadcast_text` SET `MaleText`='让神鹤指引你的脚步。' WHERE `ID`=65202;
UPDATE `broadcast_text` SET `MaleText`='不！回来，懦夫！' WHERE `ID`=65203;
UPDATE `broadcast_text` SET `MaleText`='唤醒者，这有许多奇妙的毒药。有些毒药可以活煮了你。有些会吞噬你的肉。有些会炸开你的肚子。$B$B这么多奇妙的毒药。' WHERE `ID`=65204;
UPDATE `broadcast_text` SET `MaleText`='快，摧毁它们。我们要追赶加丁！' WHERE `ID`=65205;
UPDATE `broadcast_text` SET `MaleText`='唤醒者，你试喝过毒药吗？开始时，你必须服用毒性非常温和的，第一次几滴就行了。$B$B然后，你很可能会生一场大病，也许甚至会失去一根或两根触须。$B$B但是，只要时间足够长，你就会慢慢适应。' WHERE `ID`=65206;
UPDATE `broadcast_text` SET `MaleText`='出发！' WHERE `ID`=65207;
UPDATE `broadcast_text` SET `MaleText`='我曾经是夏柯希尔女皇最看重的皇家炼金术士，技术无人能及。' WHERE `ID`=65208;
UPDATE `broadcast_text` SET `MaleText`='唉！我记得当时昂舒克还微不足道，不敢配制他的第一份毒药。我量他不敢独自面对我。然后，我们将比比谁的炼金术才是终极的。' WHERE `ID`=65209;
UPDATE `broadcast_text` SET `MaleText`='向韶天鞠躬行礼！' WHERE `ID`=65210;
UPDATE `broadcast_text` SET `MaleText`='你太弱了！' WHERE `ID`=65211;
UPDATE `broadcast_text` SET `MaleText`='傻孩子。' WHERE `ID`=65212;
UPDATE `broadcast_text` SET `MaleText`='他就在那！现在杀了他，$p！' WHERE `ID`=65213;
UPDATE `broadcast_text` SET `MaleText`='啊，又一个来自迷雾之外的旅行者。' WHERE `ID`=65214;
UPDATE `broadcast_text` SET `MaleText`='一万年前，末代熊猫人皇帝曾向我讨教治国之道。他也是一个充满矛盾的人。让我们看看你是否正确，踏岚。看看这个陌生人如何应对灵魂的骚动。' WHERE `ID`=65215;
UPDATE `broadcast_text` SET `MaleText`='很快他们将霸占整个大陆！我们何以划清界限？' WHERE `ID`=65216;
UPDATE `broadcast_text` SET `MaleText`='我们在翡翠林亲眼目睹了你所谓的“帮助”。那些“部落”，还有你的“联盟”——你们连自身都无法掌控，你们真是悲哀。' WHERE `ID`=65217;
UPDATE `broadcast_text` SET `MaleText`='草民，跪下。' WHERE `ID`=65218;
UPDATE `broadcast_text` SET `MaleText`='可怜。' WHERE `ID`=65219;
UPDATE `broadcast_text` SET `MaleText`='我们是来提供援助的。我们能帮忙保护溪谷。' WHERE `ID`=65220;
UPDATE `broadcast_text` SET `MaleText`='快去阻止加丁！别管这个女亡灵了！' WHERE `ID`=65221;
UPDATE `broadcast_text` SET `MaleText`='<他专心地俯视大厅。>' WHERE `ID`=65222;
UPDATE `broadcast_text` SET `MaleText`='|TInterface\\Icons\\ability_warlock_baneofhavoc:20|t%s开始施放|cFFFF0000|Hspell:126299|h[灵魂释放]|h|r！快跑开！' WHERE `ID`=65223;
UPDATE `broadcast_text` SET `MaleText`='这一刻终于到来了。' WHERE `ID`=65224;
UPDATE `broadcast_text` SET `MaleText`='结束了。诅咒被解除。谢谢你，$p。谢谢！' WHERE `ID`=65225;
UPDATE `broadcast_text` SET `MaleText`='我饿了！' WHERE `ID`=65226;
UPDATE `broadcast_text` SET `MaleText`='我必须吃东西！' WHERE `ID`=65227;
UPDATE `broadcast_text` SET `MaleText`='这么说，金莲教也来了……' WHERE `ID`=65228;
UPDATE `broadcast_text` SET `MaleText`='你们太迟了。碧玉军团是我的了。' WHERE `ID`=65229;
UPDATE `broadcast_text` SET `MaleText`='而有了他们，我将以雷电之王的名义碾碎金莲教，夺回锦绣谷！' WHERE `ID`=65230;
UPDATE `broadcast_text` SET `MaleText`='死吧，爬虫！' WHERE `ID`=65231;
UPDATE `broadcast_text` SET `MaleText`='无穷无尽的碧玉军团归我掌握！' WHERE `ID`=65232;
UPDATE `broadcast_text` SET `MaleText`='你那潜行者朋友自以为身手矫健。' WHERE `ID`=65233;
UPDATE `broadcast_text` SET `MaleText`='我的石雕将碾碎他的生命，只留下四分五裂的躯壳。' WHERE `ID`=65234;
UPDATE `broadcast_text` SET `MaleText`='他被你送上了绝路……' WHERE `ID`=65235;
UPDATE `broadcast_text` SET `MaleText`='多么高尚……来拯救一个必死的朋友……' WHERE `ID`=65236;
UPDATE `broadcast_text` SET `MaleText`='……徒劳无功。抓住他们！' WHERE `ID`=65237;
UPDATE `broadcast_text` SET `MaleText`='你的挣扎毫无意义。' WHERE `ID`=65238;
UPDATE `broadcast_text` SET `MaleText`='你对这座山谷蕴藏的强大秘密一无所知。我将得到它们，消灭你们所有人。' WHERE `ID`=65239;
UPDATE `broadcast_text` SET `MaleText`='将这些俘虏投进囚笼。让下面的人看好他们。' WHERE `ID`=65240;
UPDATE `broadcast_text` SET `MaleText`='我的下一个伟大的冒险即将开始。$B$B我看到的那是一道圣光吗？' WHERE `ID`=65241;
UPDATE `broadcast_text` SET `MaleText`='雷电之王的战盔……' WHERE `ID`=65242;
UPDATE `broadcast_text` SET `MaleText`='看来我的守卫都是废物。我还得亲自来对付你们。' WHERE `ID`=65243;
UPDATE `broadcast_text` SET `MaleText`='这次就不用囚笼了，我要直接把你们的四肢扯下来！' WHERE `ID`=65244;
UPDATE `broadcast_text` SET `MaleText`='屈服于我的力量！' WHERE `ID`=65245;
UPDATE `broadcast_text` SET `MaleText`='我要熄灭你的生命之火！' WHERE `ID`=65246;
UPDATE `broadcast_text` SET `MaleText`='我要撕裂你的灵魂！' WHERE `ID`=65247;
UPDATE `broadcast_text` SET `MaleText`='暴力。看见没有？充满了他们的身体。' WHERE `ID`=65248;
UPDATE `broadcast_text` SET `MaleText`='你没我想得那么弱，但战盔还是我的……' WHERE `ID`=65249;
UPDATE `broadcast_text` SET `MaleText`='啊啊！！法师，我们下次见面时，我一定要让你人头落地。' WHERE `ID`=65250;
UPDATE `broadcast_text` SET `MaleText`='对……我们是战士。可我们来自饱经肆虐的土地。我们击退过恶魔，也击退过死亡，甚至阻止过世界末日的到来！' WHERE `ID`=65251;
UPDATE `broadcast_text` SET `MaleText`='是谁竟敢打扰我？跪下！让我看看你那懦弱的脸！' WHERE `ID`=65252;
UPDATE `broadcast_text` SET `MaleText`='准备受死吧，恶棍！' WHERE `ID`=65253;
UPDATE `broadcast_text` SET `MaleText`='啊哈哈哈！真是可怜的生物！' WHERE `ID`=65254;
UPDATE `broadcast_text` SET `MaleText`='你不配让我动手。达苟！碾碎这只微不足道的跳蚤！' WHERE `ID`=65255;
UPDATE `broadcast_text` SET `MaleText`='用我的长矛终结你！' WHERE `ID`=65256;
UPDATE `broadcast_text` SET `MaleText`='颤抖着迎接你的末日吧！' WHERE `ID`=65257;
UPDATE `broadcast_text` SET `MaleText`='是的。他们很强，有很多值得我们学习的地方。' WHERE `ID`=65258;
UPDATE `broadcast_text` SET `MaleText`='我要让你瞧瞧督军的真正力量！' WHERE `ID`=65259;
UPDATE `broadcast_text` SET `MaleText`='你无路可走了，懦夫！' WHERE `ID`=65260;
UPDATE `broadcast_text` SET `MaleText`='蠢货。你竟然妄想与魔古帝国展开全面对抗？' WHERE `ID`=65261;
UPDATE `broadcast_text` SET `MaleText`='你休想痛痛快快地死，懦夫。' WHERE `ID`=65262;
UPDATE `broadcast_text` SET `MaleText`='你太没用了！' WHERE `ID`=65263;
UPDATE `broadcast_text` SET `MaleText`='我要粉碎你！' WHERE `ID`=65264;
UPDATE `broadcast_text` SET `MaleText`='我们要夺回本该属于我们的一切！' WHERE `ID`=65265;
UPDATE `broadcast_text` SET `MaleText`='愚不可及，自作自受！' WHERE `ID`=65266;
UPDATE `broadcast_text` SET `MaleText`='我获得了新生！' WHERE `ID`=65267;
UPDATE `broadcast_text` SET `MaleText`='我体内的血液里流满了毒素。我再也不怕任何毒药了。我可真是自己的杰作！' WHERE `ID`=65268;
UPDATE `broadcast_text` SET `MaleText`='你不想尝尝毒药吗，唤醒者？一滴也不要？' WHERE `ID`=65269;
UPDATE `broadcast_text` SET `MaleText`='我再也不是螳螂妖了。我变得……更加强大。' WHERE `ID`=65270;
UPDATE `broadcast_text` SET `MaleText`='我想要学习烹炒之道。', `FemaleText`='我想要学习烹炒之道。' WHERE `ID`=65271;
UPDATE `broadcast_text` SET `MaleText`='我想要学习酿造之道。', `FemaleText`='我想要学习酿造之道。' WHERE `ID`=65272;
UPDATE `broadcast_text` SET `MaleText`='我们赞同为正义事业而战是光荣的：如保卫家园或家人。可复仇呢？愤怒呢？我能在此人内心深处感觉到这些情绪。' WHERE `ID`=65273;
UPDATE `broadcast_text` SET `FemaleText`='我每天都存入各种新旧资料。有时是古老的智慧书卷，有时则是某位墨水大师创作的山谷写生图。$b$b我们保存着这些知识，以便让后人能从我们的成功……和失败中借鉴一二。' WHERE `ID`=65274;
UPDATE `broadcast_text` SET `MaleText`='站到高处，避开暗影之雾！', `FemaleText`='站到高处，避开暗影之雾！' WHERE `ID`=65275;
UPDATE `broadcast_text` SET `MaleText`='|TInterface\\Icons\\inv_misc_gem_bloodstone_03:20|t%s变成了|cFFFF0000|Hspell:126384|h[红色花岗岩]|h|r！' WHERE `ID`=65276;
UPDATE `broadcast_text` SET `MaleText`='|TInterface\\Icons\\inv_misc_gem_stone_01:20|t%s变成了|cFFFF0000|Hspell:126401|h[绿色花岗岩]|h|r！' WHERE `ID`=65277;
UPDATE `broadcast_text` SET `MaleText`='|TInterface\\Icons\\inv_ore_cobalt:20|t%s变成了|cFFFF0000|Hspell:126405|h[蓝色花岗岩]|h|r！' WHERE `ID`=65278;
