UPDATE `broadcast_text` SET `MaleText`='我想要学习蒸烧之道。', `FemaleText`='我想要学习蒸烧之道。' WHERE `ID`=65281;
UPDATE `broadcast_text` SET `MaleText`='我想要学习烘焙之道。', `FemaleText`='我想要学习烘焙之道。' WHERE `ID`=65282;
UPDATE `broadcast_text` SET `MaleText`='嗯？', `FemaleText`='嗯？' WHERE `ID`=65283;
UPDATE `broadcast_text` SET `MaleText`='闻上去香极了，是吧？', `FemaleText`='闻上去香极了，是吧？' WHERE `ID`=65284;
UPDATE `broadcast_text` SET `MaleText`='你需要什么吗？', `FemaleText`='你需要什么吗？' WHERE `ID`=65285;
UPDATE `broadcast_text` SET `MaleText`='你想要学习如何烹饪吗？', `FemaleText`='你想要学习如何烹饪吗？' WHERE `ID`=65286;
UPDATE `broadcast_text` SET `MaleText`='我想要学习熊猫人烹饪之法。', `FemaleText`='我想要学习熊猫人烹饪之法。' WHERE `ID`=65287;
UPDATE `broadcast_text` SET `MaleText`='我需要给厨房补充些食材和炊具。', `FemaleText`='我需要给厨房补充些食材和炊具。' WHERE `ID`=65288;
UPDATE `broadcast_text` SET `MaleText`='在黎明破晓时分，重锤将要砸落。' WHERE `ID`=65289;
UPDATE `broadcast_text` SET `MaleText`='生命中什么最美好？\n当然是小曲和美酒啊，兄弟们！' WHERE `ID`=65290;
UPDATE `broadcast_text` SET `MaleText`='我喜欢女人就像我喜欢啤酒——丰满而醇厚。' WHERE `ID`=65291;
UPDATE `broadcast_text` SET `MaleText`='我为爱甘愿付出一切。可我不会这么做。至少，现在不行。' WHERE `ID`=65292;
UPDATE `broadcast_text` SET `FemaleText`='这群小子可真麻烦。' WHERE `ID`=65293;
UPDATE `broadcast_text` SET `FemaleText`='我答应带他们在这儿野餐，可这里太危险了。就在几天前，我听说有几个像你一样的陌生人打了起来。$b$b还有个从……龟背上来的人。$b$b我一直以为那海龟只是个传说。' WHERE `ID`=65294;
UPDATE `broadcast_text` SET `FemaleText`='我们这里并不常遭遇掠食者。有时，如果下雨的话，蜥蜴人会出现。可他们只在电闪雷鸣的暴风雨来袭时才会来。' WHERE `ID`=65295;
UPDATE `broadcast_text` SET `MaleText`='妈妈！刘总是找我麻烦！' WHERE `ID`=65296;
UPDATE `broadcast_text` SET `MaleText`='刘抢走了我的锦鱼人饰品！' WHERE `ID`=65297;
UPDATE `broadcast_text` SET `MaleText`='刘刚才踩了我一脚！' WHERE `ID`=65298;
UPDATE `broadcast_text` SET `MaleText`='妈妈！刘总是像个猢狲一样！' WHERE `ID`=65299;
UPDATE `broadcast_text` SET `MaleText`='妈妈！刘打了我一拳！' WHERE `ID`=65300;
UPDATE `broadcast_text` SET `MaleText`='不，我没有！' WHERE `ID`=65301;
UPDATE `broadcast_text` SET `MaleText`='是他先惹我的！' WHERE `ID`=65302;
UPDATE `broadcast_text` SET `MaleText`='是你让我这么做的！' WHERE `ID`=65303;
UPDATE `broadcast_text` SET `MaleText`='不是！' WHERE `ID`=65304;
UPDATE `broadcast_text` SET `FemaleText`='够了。你们俩简直是一对猢狲！' WHERE `ID`=65305;
UPDATE `broadcast_text` SET `FemaleText`='要是你们不听话，我就马上结束野餐，带你们回家。你们愿意这样吗？' WHERE `ID`=65306;
UPDATE `broadcast_text` SET `FemaleText`='泰，别说你哥哥坏话了。刘，你也别给你弟弟说坏话的理由。' WHERE `ID`=65307;
UPDATE `broadcast_text` SET `FemaleText`='你们两个都给我住手。别弄得自己傻乎乎的。你们就不能像聪明的锦鱼人一样好好相处吗？还是说，你们就乐意毛毛躁躁地像个猢狲？' WHERE `ID`=65308;
UPDATE `broadcast_text` SET `MaleText`='发起挑战吧。' WHERE `ID`=65309;
UPDATE `broadcast_text` SET `MaleText`='这也许会让你茫然迷失，唤醒者。第一次亲眼看见，总是很困难的。' WHERE `ID`=65310;
UPDATE `broadcast_text` SET `MaleText`='非常好……金铁酒仙。' WHERE `ID`=65311;
UPDATE `broadcast_text` SET `MaleText`='我们都是暴风雨的儿女！' WHERE `ID`=65312;
UPDATE `broadcast_text` SET `FemaleText`='我一直以为巨魔只在古老的故事中存在。' WHERE `ID`=65313;
UPDATE `broadcast_text` SET `FemaleText`='谢谢你，$p！是你的勇气激励着我们战斗。' WHERE `ID`=65314;
UPDATE `broadcast_text` SET `FemaleText`='真是一场艰苦的战斗。我们从前只需要提防蜥蜴人突袭者和偶尔前来捣乱的饥饿猢狲。$b$b那些巨魔……他们作战的方式很不一样。' WHERE `ID`=65315;
UPDATE `broadcast_text` SET `FemaleText`='那些巨魔在找什么？' WHERE `ID`=65316;
UPDATE `broadcast_text` SET `MaleText`='现在你会看见。叛徒就混在我们自己人里。' WHERE `ID`=65317;
UPDATE `broadcast_text` SET `MaleText`='真是可怕的战斗。' WHERE `ID`=65318;
UPDATE `broadcast_text` SET `MaleText`='我现在真希望自己年少在禅院里受训时，没在防御课上打瞌睡。' WHERE `ID`=65319;
UPDATE `broadcast_text` SET `MaleText`='那些巨魔们想干什么？这只是个简单的小渔村。' WHERE `ID`=65320;
UPDATE `broadcast_text` SET `MaleText`='巨魔。那些是真正的巨魔！我们听过他们的传说。可现在亲眼看见了。他们跟故事里说的一样凶残。' WHERE `ID`=65321;
UPDATE `broadcast_text` SET `MaleText`='没错，愤怒在我们周身流淌。可我们懂得控制。兽人曾被愤怒驱策——终日活在对鲜血的渴望中——但还是战胜了它。' WHERE `ID`=65322;
UPDATE `broadcast_text` SET `MaleText`='你们想战胜的，只是彼此！' WHERE `ID`=65323;
UPDATE `broadcast_text` SET `MaleText`='只有死人才不会愤怒。但我们要学会克制。击败心中的愤怒，才能获得力量。' WHERE `ID`=65324;
UPDATE `broadcast_text` SET `MaleText`='|TInterface\\Icons\\ability_warrior_battleshout.blp:20|t牢非的灵魂施放了|cFFFF0000|Hspell:126471|h[倚强凌弱]|h|r！' WHERE `ID`=65325;
UPDATE `broadcast_text` SET `MaleText`='说得好，智。来自迷雾之外的陌生人们虽然不缺乏热情，但我们得看看他们的自制力。愤怒出自仇恨，仇恨乃万苦之源。看，这就是你心中仇恨的模样！' WHERE `ID`=65326;
UPDATE `broadcast_text` SET `MaleText`='看见没有？这些外来者如此憎恨彼此！他们身披仇恨上阵，再把仇恨带进坟墓！' WHERE `ID`=65327;
UPDATE `broadcast_text` SET `MaleText`='不，那不是真的——对我们来说绝对不止这样！' WHERE `ID`=65328;
UPDATE `broadcast_text` SET `MaleText`='真有趣。他们带来了很多东西，但也带来了战争的阴影。' WHERE `ID`=65329;
UPDATE `broadcast_text` SET `MaleText`='和平终将来临。我发誓。往昔的仇恨将不复存在。你要相信我。' WHERE `ID`=65330;
UPDATE `broadcast_text` SET `MaleText`='|TInterface\\Icons\\ability_searingarrow.blp:20|t火霜施放了|cFFFF0000|Hspell:126304|h[烈焰之箭]|h|r！' WHERE `ID`=65331;
UPDATE `broadcast_text` SET `MaleText`='|TInterface\\Icons\\spell_frost_iceshard.blp:20|t火霜施放了|cFFFF0000|Hspell:126321|h[霜冻箭矢]|h|r！' WHERE `ID`=65332;
UPDATE `broadcast_text` SET `MaleText`='科尔里克！你为女皇效命多久了？！' WHERE `ID`=65333;
UPDATE `broadcast_text` SET `MaleText`='我看见英杰被唤醒了。' WHERE `ID`=65334;
UPDATE `broadcast_text` SET `MaleText`='英杰满嘴胡话，唤醒者。封存让他精神失常了。' WHERE `ID`=65335;
