UPDATE `broadcast_text` SET `FemaleText`='欺骗到此为止吧。' WHERE `ID`=65471;
UPDATE `broadcast_text` SET `FemaleText`='你好，我叫莉莉安。你不会介意我拿走这两柄利刃，对吧？' WHERE `ID`=65472;
UPDATE `broadcast_text` SET `FemaleText`='蒙面的十字军战士凝视着检查官被刀片刺穿的尸体。' WHERE `ID`=65473;
UPDATE `broadcast_text` SET `MaleText`='……哎呦？' WHERE `ID`=65474;
UPDATE `broadcast_text` SET `MaleText`='是的……爸爸。对不起，我脑袋被那东西给控制住了。' WHERE `ID`=65475;
UPDATE `broadcast_text` SET `MaleText`='滚出……我儿子……的脑袋！' WHERE `ID`=65476;
UPDATE `broadcast_text` SET `MaleText`='嗯，那至少是个开始。你记得自己是谁吗？' WHERE `ID`=65477;
UPDATE `broadcast_text` SET `MaleText`='那是精神控制，儿子。是有区别的。别担心。如果“王牌狩猎”那么容易，那就人人都能做到了。' WHERE `ID`=65478;
UPDATE `broadcast_text` SET `MaleText`='雾锁猢狲。', `FemaleText`='雾锁猢狲。' WHERE `ID`=65479;
