UPDATE `broadcast_text` SET `MaleText`='遵照女皇的旨意，卡拉克西将被遣散。' WHERE `ID`=67842;
UPDATE `broadcast_text` SET `MaleText`='亵渎！' WHERE `ID`=67843;
UPDATE `broadcast_text` SET `MaleText`='我看到绝望的卡拉克西已经沦落到去挖化石了。好极了，让我们做个了结吧。' WHERE `ID`=67844;
UPDATE `broadcast_text` SET `MaleText`='“毫发未伤”，确实如此。' WHERE `ID`=67846;
UPDATE `broadcast_text` SET `MaleText`='前进！卡拉克西已经公然显露叛徒的身份。消灭他们，一个不留。' WHERE `ID`=67847;
UPDATE `broadcast_text` SET `MaleText`='唤醒者，你的功劳为你赢得了我们的信任。' WHERE `ID`=67848;
UPDATE `broadcast_text` SET `MaleText`='你将受到嘉奖。随我来。' WHERE `ID`=67849;
UPDATE `broadcast_text` SET `MaleText`='我们螳螂妖是个古老的种族。你结识的熊猫人——不过是孩童。他们有自己要扮演的角色。' WHERE `ID`=67850;
UPDATE `broadcast_text` SET `MaleText`='每次轮回，我们年轻的虫群涌上长城。熊猫人杀光弱者。而强者得以返回。' WHERE `ID`=67851;
UPDATE `broadcast_text` SET `MaleText`='代代繁衍，我们变得越发强大。' WHERE `ID`=67852;
UPDATE `broadcast_text` SET `MaleText`='在你们之前，我们的帝国早已广大无边。我们与姐妹王国安其拉和艾卓-尼鲁布平分这个世界。' WHERE `ID`=67853;
UPDATE `broadcast_text` SET `MaleText`='我们的神祗众多而强大。我们螳螂妖崇拜的是七首亚煞极。' WHERE `ID`=67854;
UPDATE `broadcast_text` SET `MaleText`='上古尊者很伟大，可发起怒来令人胆寒。他吞噬希冀，招引绝望；他吸进勇气，呼出恐惧。' WHERE `ID`=67855;
UPDATE `broadcast_text` SET `MaleText`='被你们称为“泰坦”的篡位者到来时，亚煞极遭到了毁灭。' WHERE `ID`=67856;
UPDATE `broadcast_text` SET `MaleText`='他最后的恐怖呼吸变成挥之不散的阴影，可跟他先前的荣耀相比不值一提。' WHERE `ID`=67857;
UPDATE `broadcast_text` SET `MaleText`='我们信任你，所以给你这个警告。' WHERE `ID`=67858;
UPDATE `broadcast_text` SET `MaleText`='你的神将不再是神，外来者。' WHERE `ID`=67859;
UPDATE `broadcast_text` SET `MaleText`='一旦上古尊者归来，螳螂妖将再一次追随他们。' WHERE `ID`=67860;
UPDATE `broadcast_text` SET `MaleText`='你们当中的智者也会如此。' WHERE `ID`=67861;
UPDATE `broadcast_text` SET `MaleText`='要说的就这么多。来吧，拿上你的奖赏。记住你今天学到的一切。' WHERE `ID`=67862;
UPDATE `broadcast_text` SET `MaleText`='我看见你也排除万难，登上了寇塔峰。你已经证明了自己的能力，有资格与我交战。' WHERE `ID`=67863;
UPDATE `broadcast_text` SET `MaleText`='嘿女士！小心点好吗！' WHERE `ID`=67864;
UPDATE `broadcast_text` SET `MaleText`='别再摆弄那根棍子了！' WHERE `ID`=67865;
