UPDATE `broadcast_text` SET `MaleText`='轻点女士！我可娇嫩得很！' WHERE `ID`=67868;
UPDATE `broadcast_text` SET `MaleText`='别再用那玩意儿戳我！' WHERE `ID`=67869;
UPDATE `broadcast_text` SET `MaleText`='干得好。你已经完成训练了。与我在玄牛神龛会面，领取奖励。' WHERE `ID`=67870;
UPDATE `broadcast_text` SET `MaleText`='怎么——不——不！他们有空军基地，秘密空军基地……我的船——我的——地狱咆哮会要了我的脑袋的！' WHERE `ID`=67871;
