UPDATE `broadcast_text` SET `FemaleText`='你愿意继续卡在树上吗？！' WHERE `ID`=67890;
UPDATE `broadcast_text` SET `FemaleText`='嘿，是你把自己卡在那的！我只是想帮你！' WHERE `ID`=67891;
