UPDATE `broadcast_text` SET `MaleText`='|TInterface\\Icons\\inv_polearm_2h_mantid_01.blp:20|t%s施放了|cFFFF0000|Hspell:131320|h[利刃灌能]|h|r，快跑！' WHERE `ID`=67949;
UPDATE `broadcast_text` SET `MaleText`='不算太糟。看来你在那边还能多耕出几块地来。' WHERE `ID`=67950;
UPDATE `broadcast_text` SET `MaleText`='让同是农夫的我给你个建议。在半山市集里可以买到各种各样的升级用品。吉娜·泥爪出售工具，商人绿野贩卖种子。' WHERE `ID`=67951;
