UPDATE `broadcast_text` SET `MaleText`='可父亲——' WHERE `ID`=69746;
UPDATE `broadcast_text` SET `MaleText`='我会亲自带领一小队勇士去跟泰兰德谈谈。安度因，我能应付。相信我，我不会犯错的。' WHERE `ID`=69747;
UPDATE `broadcast_text` SET `MaleText`='……我相信你，父亲。' WHERE `ID`=69748;
UPDATE `broadcast_text` SET `MaleText`='向吉尔尼斯国王，吉恩·格雷迈恩致敬！', `FemaleText`='向吉尔尼斯国王，吉恩·格雷迈恩致敬！' WHERE `ID`=69749;
