UPDATE `broadcast_text` SET `MaleText`='我们的船只！这到底是怎么回事？！' WHERE `ID`=70707;
UPDATE `broadcast_text` SET `MaleText`='我终于自由了！反叛的臭猴子们，我终于摆脱你们了。' WHERE `ID`=70708;
UPDATE `broadcast_text` SET `MaleText`='你就排在下一位！', `FemaleText`='你就排在下一位！' WHERE `ID`=70709;
UPDATE `broadcast_text` SET `MaleText`='帝国……必将……再度崛起。' WHERE `ID`=70710;
UPDATE `broadcast_text` SET `MaleText`='我要把你从生死簿上除名！' WHERE `ID`=70711;
UPDATE `broadcast_text` SET `MaleText`='有本事就把我从这里赶出去！' WHERE `ID`=70712;
UPDATE `broadcast_text` SET `FemaleText`='为了夺日者！' WHERE `ID`=70713;
UPDATE `broadcast_text` SET `FemaleText`='所以必须做个了断了，对吧？' WHERE `ID`=70714;
UPDATE `broadcast_text` SET `MaleText`='该死……银色盟约的人也来了。' WHERE `ID`=70715;
UPDATE `broadcast_text` SET `MaleText`='但愿能成功。根据我的调查，这个青玉战神不是什么好东西。准备好战斗吧。' WHERE `ID`=70716;
UPDATE `broadcast_text` SET `MaleText`='这个屋子在旋转？' WHERE `ID`=70717;
UPDATE `broadcast_text` SET `MaleText`='……*嗝*' WHERE `ID`=70718;
UPDATE `broadcast_text` SET `MaleText`='我的酒洒啦！' WHERE `ID`=70719;
UPDATE `broadcast_text` SET `FemaleText`='能请我喝一杯吗？' WHERE `ID`=70720;
UPDATE `broadcast_text` SET `FemaleText`='没错，布鲁姆就是我的爱人，我们俩就像是一个豆荚里的两颗豆子，即使他是轻量级选手，我也一样爱他！' WHERE `ID`=70721;
UPDATE `broadcast_text` SET `FemaleText`='你有话和我说？没问题，你负责说，我负责喝！' WHERE `ID`=70722;
UPDATE `broadcast_text` SET `FemaleText`='你最好别相信我说的任何话。算了，当我没说过。' WHERE `ID`=70723;
UPDATE `broadcast_text` SET `FemaleText`='啊，没错，那些关于我的谣言满天飞，可惜都是假的。什么我小时候是暗月马戏团的吉祥物，五岁生日那天杀了六个恶魔——用的还是一把勺子——我最喜欢这段了。但事实上，我只是个普通的金发姑娘。人们就喜欢相信那些有的没的。' WHERE `ID`=70724;
UPDATE `broadcast_text` SET `FemaleText`='我喜欢这个地方。在别的地方，那些人总是叫我“暴力孤僻女”。好吧，其实在这儿他们也这么叫我，不过至少他们是当着我的面，并且面带着微笑地叫这个名字。' WHERE `ID`=70725;
UPDATE `broadcast_text` SET `MaleText`='我闻起来像不像火腿？' WHERE `ID`=70726;
UPDATE `broadcast_text` SET `MaleText`='我过敏了，得吃点药。' WHERE `ID`=70727;
UPDATE `broadcast_text` SET `MaleText`='前几天的一个晚上，有人扔了个球过来，还叫我去捡。我照他说的做了，只不过把球和他脑袋一起扔回去了。不用说，他没接着那个球。' WHERE `ID`=70728;
UPDATE `broadcast_text` SET `FemaleText`='我总是为血角欢呼。那头愤怒的铲齿鹿看似娇小，却总是能让那些大块头吃尽苦头。' WHERE `ID`=70729;
UPDATE `broadcast_text` SET `FemaleText`='城市生活会改变一名德鲁伊。上周我生平第一次使用了公共飞行路线……感觉真是不错啊。' WHERE `ID`=70730;
UPDATE `broadcast_text` SET `FemaleText`='大多数德鲁伊都很古板，不过我是个例外，我是个真正的聚会动物。我的笑话说完了。你该笑了。' WHERE `ID`=70731;
UPDATE `broadcast_text` SET `MaleText`='我能轻松打断四层强化松木板，只是要借用一下你的脑袋。要我给你做个示范吗？' WHERE `ID`=70732;
UPDATE `broadcast_text` SET `MaleText`='我不知道为啥这么多武僧都把酒桶乱扔。真浪费。' WHERE `ID`=70733;
UPDATE `broadcast_text` SET `MaleText`='当然，我会上场的，等我把这两桶酒喝完。' WHERE `ID`=70734;
UPDATE `broadcast_text` SET `FemaleText`='啊，对不起，我不能请你喝酒了。我最近有点小穷，但我相信我会时来运转的。' WHERE `ID`=70735;
UPDATE `broadcast_text` SET `FemaleText`='这地方看起来很硬派，但这里的人其实内心里都是软蛋。' WHERE `ID`=70736;
UPDATE `broadcast_text` SET `FemaleText`='哦，没错，我刚到奥格瑞玛不久。这不明摆着的吗？' WHERE `ID`=70737;
UPDATE `broadcast_text` SET `FemaleText`='你应该排队参加搏击——这样我就能笑上好一阵了。' WHERE `ID`=70738;
UPDATE `broadcast_text` SET `FemaleText`='继续瞪着我。我喜欢尴尬的沉默。' WHERE `ID`=70739;
UPDATE `broadcast_text` SET `FemaleText`='弱者才穿鞋。' WHERE `ID`=70740;
UPDATE `broadcast_text` SET `FemaleText`='上一回我在竞技场里把对手打到边哭边逃。按说对手打架打到一半就逃这不算什么稀奇事儿，但这可是我头一回看到鳄鱼流眼泪。' WHERE `ID`=70741;
UPDATE `broadcast_text` SET `FemaleText`='“娜丽，把这东西举起来！”，他们总是这么冲我嚷嚷。为什么不能说“娜丽，能跳支舞吗？”我可是个伟大的舞者。' WHERE `ID`=70742;
UPDATE `broadcast_text` SET `FemaleText`='斯特林顿公爵就是个渣渣。他吹牛吹得厉害，但连自己的剑都拿不起来。啊，没错，他的名字也是瞎编的，我相信你肯定猜到了。' WHERE `ID`=70743;
UPDATE `broadcast_text` SET `MaleText`='你想吃拳头了，笨蛋？' WHERE `ID`=70744;
UPDATE `broadcast_text` SET `MaleText`='昨晚我教训了三个兽人和一个牛头人，连一根指甲都没刮花。' WHERE `ID`=70745;
UPDATE `broadcast_text` SET `MaleText`='你搬过东西吗，兄弟？' WHERE `ID`=70746;
UPDATE `broadcast_text` SET `MaleText`='不，那是我的大腿骨，但是我见到你很高兴。' WHERE `ID`=70747;
UPDATE `broadcast_text` SET `MaleText`='小鸡就喜欢啄伤疤，所以你知道为啥我这么受女士们欢迎了吧。' WHERE `ID`=70748;
UPDATE `broadcast_text` SET `MaleText`='你喜欢眼前这一切吗？你当然喜欢了。' WHERE `ID`=70749;
UPDATE `broadcast_text` SET `MaleText`='为什么每个人都知道我的名字？' WHERE `ID`=70750;
UPDATE `broadcast_text` SET `MaleText`='我很想抱抱你。' WHERE `ID`=70751;
UPDATE `broadcast_text` SET `MaleText`='掩护我，伙计。' WHERE `ID`=70752;
UPDATE `broadcast_text` SET `MaleText`='睁大你的眼睛。' WHERE `ID`=70753;
UPDATE `broadcast_text` SET `MaleText`='跟紧我。' WHERE `ID`=70754;
UPDATE `broadcast_text` SET `MaleText`='小心——那里有东西。' WHERE `ID`=70755;
UPDATE `broadcast_text` SET `MaleText`='再见。' WHERE `ID`=70756;
UPDATE `broadcast_text` SET `MaleText`='啊……陛下？' WHERE `ID`=70757;
UPDATE `broadcast_text` SET `MaleText`='该死的蜥蜴人。随我战斗，兄弟们！' WHERE `ID`=70758;
UPDATE `broadcast_text` SET `MaleText`='抱歉。我的名字叫安度因·乌瑞恩。我和这位勇士需要你的帮助。' WHERE `ID`=70759;
UPDATE `broadcast_text` SET `MaleText`='谢谢你。但现在可不是开派对的时候。一个穷凶极恶的军阀已经找到了圣钟，他的名字叫加尔鲁什。我们需要祥和钟杵来对抗他。' WHERE `ID`=70760;
UPDATE `broadcast_text` SET `MaleText`='而且，调查显示你是最后一个——' WHERE `ID`=70761;
UPDATE `broadcast_text` SET `MaleText`='这会有所帮助。' WHERE `ID`=70762;
UPDATE `broadcast_text` SET `MaleText`='继续战斗。' WHERE `ID`=70763;
UPDATE `broadcast_text` SET `MaleText`='万灵与你同在。' WHERE `ID`=70764;
UPDATE `broadcast_text` SET `MaleText`='用这个治疗你！' WHERE `ID`=70765;
UPDATE `broadcast_text` SET `MaleText`='把他拖进陷阱！' WHERE `ID`=70766;
UPDATE `broadcast_text` SET `MaleText`='把他引到陷阱里！' WHERE `ID`=70767;
UPDATE `broadcast_text` SET `MaleText`='我设了个陷阱。' WHERE `ID`=70768;
UPDATE `broadcast_text` SET `MaleText`='把他引到陷阱里来！' WHERE `ID`=70769;
UPDATE `broadcast_text` SET `MaleText`='别让这些野兽靠近我！' WHERE `ID`=70770;
UPDATE `broadcast_text` SET `MaleText`='又来了。' WHERE `ID`=70771;
UPDATE `broadcast_text` SET `MaleText`='你以前和这些家伙战斗过吗？' WHERE `ID`=70772;
UPDATE `broadcast_text` SET `MaleText`='看来他们空有武器，却没有脑子。' WHERE `ID`=70773;
UPDATE `broadcast_text` SET `MaleText`='我们可以把船开进去。只要做一点改装……' WHERE `ID`=70774;
UPDATE `broadcast_text` SET `MaleText`='啊……完成了！自行式蜥蜴人宰杀机。' WHERE `ID`=70775;
UPDATE `broadcast_text` SET `MaleText`='一人操作机枪，其他人步行。' WHERE `ID`=70776;
UPDATE `broadcast_text` SET `MaleText`='杀光那些爬虫！' WHERE `ID`=70777;
UPDATE `broadcast_text` SET `MaleText`='哎呀，甩掉它！' WHERE `ID`=70778;
UPDATE `broadcast_text` SET `MaleText`='他们在破坏我们的船！' WHERE `ID`=70779;
UPDATE `broadcast_text` SET `MaleText`='干掉那个巫师！' WHERE `ID`=70780;
UPDATE `broadcast_text` SET `MaleText`='让那些畜生离船远点！' WHERE `ID`=70781;
UPDATE `broadcast_text` SET `MaleText`='到了！在这儿停船。' WHERE `ID`=70782;
UPDATE `broadcast_text` SET `MaleText`='格里兹尔看着船。其他人跟我走。' WHERE `ID`=70783;
UPDATE `broadcast_text` SET `MaleText`='给！它能帮你对付虫子。' WHERE `ID`=70784;
UPDATE `broadcast_text` SET `MaleText`='那我就……留下吧。好吧…别忘了我！' WHERE `ID`=70785;
UPDATE `broadcast_text` SET `MaleText`='喔吼！一个大王的儿子！手脚发麻。手脚发麻。腿没睡醒。手没睡醒。脑袋也没睡醒。' WHERE `ID`=70786;
UPDATE `broadcast_text` SET `MaleText`='这似乎是某种孵化室……' WHERE `ID`=70787;
UPDATE `broadcast_text` SET `MaleText`='小心！洞顶塌了！' WHERE `ID`=70788;
UPDATE `broadcast_text` SET `MaleText`='喔？陛下？我可不是什么皇帝，小家伙。我是美猴王！' WHERE `ID`=70789;
UPDATE `broadcast_text` SET `MaleText`='这些生物不太正常。' WHERE `ID`=70790;
UPDATE `broadcast_text` SET `MaleText`='帮助？你把我从玉石里救出来了，不用一直被关着了！我要为你开一个最最大的派对！' WHERE `ID`=70791;
UPDATE `broadcast_text` SET `MaleText`='这就是我们要找的地方。' WHERE `ID`=70792;
UPDATE `broadcast_text` SET `MaleText`='酋长发现魔古族与这些生物密切相关。' WHERE `ID`=70793;
UPDATE `broadcast_text` SET `MaleText`='巨魔！你最了解这……巫毒玩意儿了。有何发现？' WHERE `ID`=70794;
UPDATE `broadcast_text` SET `MaleText`='哦……那个丢失的祥和钟杵，是吗？真是个傻名字。那么你来找到美猴王，是要问罪于他？' WHERE `ID`=70795;
UPDATE `broadcast_text` SET `MaleText`='“巫毒玩意儿”' WHERE `ID`=70796;
UPDATE `broadcast_text` SET `MaleText`='啊哈哈哈！别担心，你来对地方了。但是先让我看看你的面相是不是讨喜。' WHERE `ID`=70797;
UPDATE `broadcast_text` SET `MaleText`='掩护我，我要调查一下……' WHERE `ID`=70798;
UPDATE `broadcast_text` SET `MaleText`='这些“魔古族”，在这里施了邪法。' WHERE `ID`=70799;
UPDATE `broadcast_text` SET `MaleText`='蜥蜴人不是天生的——而是创造出来的。是扭曲成形的血肉。' WHERE `ID`=70800;
UPDATE `broadcast_text` SET `MaleText`='这是最黑暗的魔法，伙计！' WHERE `ID`=70801;
UPDATE `broadcast_text` SET `MaleText`='没错！能制造战士的血肉塑形之力。这……正合酋长之意！' WHERE `ID`=70802;
UPDATE `broadcast_text` SET `MaleText`='加尔鲁什想成为神？制造怪物？这有违部落精神！' WHERE `ID`=70803;
UPDATE `broadcast_text` SET `MaleText`='他早知道你是个叛徒。' WHERE `ID`=70804;
