UPDATE `broadcast_text` SET `MaleText`='它充满了泰坦的魔力，那是创造的语言——' WHERE `ID`=72381;
UPDATE `broadcast_text` SET `MaleText`='噢——我看见了——数百万个世界——闪烁着完美的光芒——其中一颗特别璀璨——噢——' WHERE `ID`=72382;
