UPDATE `broadcast_text` SET `FemaleText`='我失败了！……我们再试一次吧！' WHERE `ID`=75877;
UPDATE `broadcast_text` SET `FemaleText`='哦不！你忘记给自己治疗了吗？' WHERE `ID`=75878;
