UPDATE `broadcast_text` SET `MaleText`='噢，天呐……飞毛腿，来帮忙！' WHERE `ID`=75880;
UPDATE `broadcast_text` SET `MaleText`='哈？……噢！' WHERE `ID`=75881;
UPDATE `broadcast_text` SET `MaleText`='啊，幻影隧道工。我和飞毛腿对付过这种敌人。小心，它们会钻洞，然后突然从新目标脚下冒出来狂啃！哈哈！' WHERE `ID`=75882;
UPDATE `broadcast_text` SET `MaleText`='啊啊……请照顾好……飞毛腿。' WHERE `ID`=75883;
UPDATE `broadcast_text` SET `MaleText`='这些幻影是无穷无尽的，但我们要尽力守住！' WHERE `ID`=75884;
UPDATE `broadcast_text` SET `MaleText`='哈哈！干得好，各位！朋友，去找罗敦开启下一轮试炼吧。' WHERE `ID`=75885;
UPDATE `broadcast_text` SET `MaleText`='我不会再倒下了！' WHERE `ID`=75886;
UPDATE `broadcast_text` SET `MaleText`='你是个高贵的兽人，纳兹戈林。很抱歉我必须这么做。' WHERE `ID`=75887;
UPDATE `broadcast_text` SET `MaleText`='你带着荣耀而战，加摩尔会让你的精神流传下去。为了部落，我的朋友。' WHERE `ID`=75888;
UPDATE `broadcast_text` SET `MaleText`='不能就这样……结束……' WHERE `ID`=75889;
UPDATE `broadcast_text` SET `MaleText`='你能否独立山巅，任由风霜侵袭，直至沧海变为桑田，高山沉入海底？' WHERE `ID`=75890;
UPDATE `broadcast_text` SET `MaleText`='让我们拭目以待吧。' WHERE `ID`=75891;
UPDATE `broadcast_text` SET `MaleText`='风刀霜剑，四面受敌。' WHERE `ID`=75892;
UPDATE `broadcast_text` SET `MaleText`='不动如山，亘古不移。' WHERE `ID`=75893;
UPDATE `broadcast_text` SET `MaleText`='想要达到目标，你必须寸步不让。' WHERE `ID`=75894;
UPDATE `broadcast_text` SET `MaleText`='坚持住！' WHERE `ID`=75895;
UPDATE `broadcast_text` SET `MaleText`='虽然被强大得超乎想象的敌人包围，毅力还是让你坚持了下来。在未来的日子里，请记住这一课。' WHERE `ID`=75896;
UPDATE `broadcast_text` SET `MaleText`='在面对空前的挑战时，你有着怎样的期盼？你想要怎样的未来？' WHERE `ID`=75897;
UPDATE `broadcast_text` SET `MaleText`='让我们开始吧。' WHERE `ID`=75898;
UPDATE `broadcast_text` SET `MaleText`='相信彼此，让别人为你带来希望！' WHERE `ID`=75899;
UPDATE `broadcast_text` SET `MaleText`='没有希望，未来就没有光明！' WHERE `ID`=75900;
UPDATE `broadcast_text` SET `MaleText`='去创造你想要的命运吧！' WHERE `ID`=75901;
UPDATE `broadcast_text` SET `MaleText`='不要放弃自己！' WHERE `ID`=75902;
UPDATE `broadcast_text` SET `MaleText`='你们的希望十分闪亮，你们团结起来后，它更是璀璨夺目。哪怕在最黑暗的地方，它也将照亮你们的道路。' WHERE `ID`=75903;
UPDATE `broadcast_text` SET `MaleText`='亲爱的英雄，真正的智慧就在你心中，也在你所作出的选择中。当面对压倒性的黑暗时，你能否作出正确的选择呢？' WHERE `ID`=75904;
UPDATE `broadcast_text` SET `MaleText`='试炼开始！' WHERE `ID`=75905;
UPDATE `broadcast_text` SET `MaleText`='倾听你内心的声音，找出真相吧！' WHERE `ID`=75906;
UPDATE `broadcast_text` SET `MaleText`='审时度势，别让危机干扰你的判断！' WHERE `ID`=75907;
UPDATE `broadcast_text` SET `MaleText`='考虑好行动的顺序！' WHERE `ID`=75908;
UPDATE `broadcast_text` SET `MaleText`='从错误中汲取教训！' WHERE `ID`=75909;
UPDATE `broadcast_text` SET `MaleText`='你的智慧帮你赢得了这次试炼。愿它能始终带你走出困境。' WHERE `ID`=75910;
UPDATE `broadcast_text` SET `MaleText`='力量。它不仅仅是指单纯的肉体强度。在面对真正的考验时，你是否能够分清力量与能力？' WHERE `ID`=75911;
UPDATE `broadcast_text` SET `MaleText`='哈哈！试炼开始！' WHERE `ID`=75912;
UPDATE `broadcast_text` SET `MaleText`='相信你的力量！' WHERE `ID`=75913;
UPDATE `broadcast_text` SET `MaleText`='你拥有改变命运的能力！' WHERE `ID`=75914;
UPDATE `broadcast_text` SET `MaleText`='不要把黑暗之力错当成真正的力量！' WHERE `ID`=75915;
UPDATE `broadcast_text` SET `MaleText`='加倍奉还！' WHERE `ID`=75916;
UPDATE `broadcast_text` SET `MaleText`='你很强大，比你自己以为的还要强大。带着这个信念勇敢迎接黑暗吧，它将会庇佑着你。' WHERE `ID`=75917;
UPDATE `broadcast_text` SET `MaleText`='啊，总算能活动了。 Lok\'tar Ogar！' WHERE `ID`=75918;
UPDATE `broadcast_text` SET `MaleText`='啊……哈……打得好……' WHERE `ID`=75919;
UPDATE `broadcast_text` SET `MaleText`='别傻了，沃金！你们没有攻城武器了！你是赢不了的！' WHERE `ID`=75920;
UPDATE `broadcast_text` SET `MaleText`='就算你们打败了它，可城门依然耸立。你们休想攻占奥格瑞玛。' WHERE `ID`=75921;
UPDATE `broadcast_text` SET `MaleText`='什么？库卡隆，到城门那边去！快！' WHERE `ID`=75922;
UPDATE `broadcast_text` SET `MaleText`='我从未被联盟打倒过。你觉得自己够强吗？' WHERE `ID`=75923;
UPDATE `broadcast_text` SET `MaleText`='我是纳兹戈林，酋长之拳，部落统帅。就算我今天难逃一死，也要光荣地战死沙场。为了部落！' WHERE `ID`=75924;
UPDATE `broadcast_text` SET `MaleText`='你训练得太糟糕了。' WHERE `ID`=75925;
UPDATE `broadcast_text` SET `MaleText`='我……虽死犹荣……Lok\'tar Ogar……' WHERE `ID`=75926;
UPDATE `broadcast_text` SET `MaleText`='啊……加摩尔……你终于变强了……能死在……你的手上……是我的荣幸……' WHERE `ID`=75927;
UPDATE `broadcast_text` SET `MaleText`='啊……你学会了很多……学得很好……光荣的战斗。' WHERE `ID`=75928;
UPDATE `broadcast_text` SET `MaleText`='我最终站在了酋长一边，因为这是我的使命，很高兴打倒我的人是你。愿你的力量……带领部落……走向繁荣昌盛。' WHERE `ID`=75929;
UPDATE `broadcast_text` SET `MaleText`='为了部落……' WHERE `ID`=75930;
UPDATE `broadcast_text` SET `MaleText`='这一天终于来了。多年来我们一起成长，一起学习，如今却在战场上兵戎相见。别幻想我会放过你，我也不会求饶。此时此刻，我们所做的一切，都是为了部落。' WHERE `ID`=75931;
UPDATE `broadcast_text` SET `MaleText`='能够与你一战是我的荣幸。Lok\'tar Ogar，为了荣耀，为了部落！' WHERE `ID`=75932;
UPDATE `broadcast_text` SET `MaleText`='很久以前，睿智的青龙教会我净化自己的灵魂并与大地融为一体，我的疑虑就此被打消了。' WHERE `ID`=75933;
UPDATE `broadcast_text` SET `MaleText`='当旅程开始时，我只会鲁莽地运用自己的力量。白虎教我学会控制，从而征服了我的仇恨、愤怒和暴虐。' WHERE `ID`=75934;
UPDATE `broadcast_text` SET `MaleText`='朱鹤看到了我内心的希望，并且教我学会自省。透过绝望的表象，我发现了希望，并由此征服了绝望。' WHERE `ID`=75935;
UPDATE `broadcast_text` SET `MaleText`='在巨大的恐惧面前，玄牛教我懂得坚毅，让我在恐怖与黑暗的时代不屈不挠，征服恐惧。' WHERE `ID`=75936;
UPDATE `broadcast_text` SET `MaleText`='你通过了智慧的试炼，并领悟了青龙之道。愿你能像我一样，有所收获。' WHERE `ID`=75937;
UPDATE `broadcast_text` SET `MaleText`='你通过了力量的试炼，并领悟了白虎之道。愿你永远记住这一课。' WHERE `ID`=75938;
UPDATE `broadcast_text` SET `MaleText`='你通过了希望的试炼，并领悟了朱鹤之道。愿它永远指引你的脚步。' WHERE `ID`=75939;
UPDATE `broadcast_text` SET `MaleText`='你通过了坚毅的试炼，并领悟了玄牛之道。愿它永远护佑你的道路。' WHERE `ID`=75940;
UPDATE `broadcast_text` SET `MaleText`='我用尽了一切办法想要移走塌方的石头！可玄牛在上，我连一块石头都搬不动。或许我得去寺院里借一把传奇武器来才行……' WHERE `ID`=75941;
UPDATE `broadcast_text` SET `MaleText`='我的朋友，请到锦绣谷中心的繁盛矿洞附近来找我。我想给你看点东西。' WHERE `ID`=75942;
UPDATE `broadcast_text` SET `MaleText`='里克里克可是很有两下子的……' WHERE `ID`=75943;
UPDATE `broadcast_text` SET `MaleText`='噢，别那么惊讶！我可是黑龙。我只忠于我自己。' WHERE `ID`=75944;
