UPDATE `broadcast_text` SET `MaleText`='里克有个主意。乱斗俱乐部！' WHERE `ID`=75947;
UPDATE `broadcast_text` SET `MaleText`='当河流转向时，我们应该顺应潮流，而非逆势而上。' WHERE `ID`=75948;
UPDATE `broadcast_text` SET `MaleText`='永远不要忘记你最伟大的朋友，他们会与你并肩作战，直到最后一刻。' WHERE `ID`=75949;
