UPDATE `broadcast_text` SET `MaleText`='%s恶毒地瞥了你一眼。' WHERE `ID`=75973;
UPDATE `broadcast_text` SET `MaleText`='够了！' WHERE `ID`=75977;
UPDATE `broadcast_text` SET `MaleText`='说，说，说！' WHERE `ID`=75978;
UPDATE `broadcast_text` SET `MaleText`='你只知道说，却从不倾听！你忽略了潘达利亚的教训！' WHERE `ID`=75979;
UPDATE `broadcast_text` SET `MaleText`='万物自有平衡之道。这智慧铭刻在我们的皮毛上：黑与白。黑暗与光明。' WHERE `ID`=75980;
UPDATE `broadcast_text` SET `MaleText`='当末代皇帝将我们的土地与外部世界隔离时，他也留下了我们的宿敌，螳螂妖。他为什么这么做？' WHERE `ID`=75981;
UPDATE `broadcast_text` SET `MaleText`='联盟和部落之间的战争也是一样。如果没有对方存在的话，他们也绝不会如此强盛。' WHERE `ID`=75982;
