UPDATE `broadcast_text` SET `MaleText`='……他毁了我的酒馆，还不给小费。真没风度。' WHERE `ID`=75984;
UPDATE `broadcast_text` SET `MaleText`='呃？' WHERE `ID`=75985;
UPDATE `broadcast_text` SET `MaleText`='……你……你不过是个倒酒的！' WHERE `ID`=75986;
UPDATE `broadcast_text` SET `MaleText`='我发誓：我要不惜一切代价让这个世界做好战争的准备。' WHERE `ID`=75987;
